import{_ as t,o as a,a as o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const h=JSON.parse('{"title":"Contribution Guide","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/contribution-guide.md","filePath":"getting-started/contribution-guide.md","lastUpdated":1790143103000}'),i={name:"getting-started/contribution-guide.md"};function s(n,e,l,u,c,d){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="contribution-guide" tabindex="-1">Contribution Guide <a class="header-anchor" href="#contribution-guide" aria-label="Permalink to &quot;Contribution Guide&quot;">​</a></h1><p>Bagisto is developed in the open at <a href="https://github.com/bagisto/bagisto" target="_blank" rel="noreferrer">bagisto/bagisto</a>. This page is for developers who want to report a problem in Bagisto or send a change to it. It says where each kind of report goes and which documentation pages you&#39;ll need; the contribution rules themselves are in the repository.</p><div class="tip custom-block"><p class="custom-block-title">Read <code>CONTRIBUTING.md</code> Before You Start</p><p><a href="https://github.com/bagisto/bagisto/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> is the source of truth for contributing to Bagisto: claiming an issue, choosing the branch to target, compiled assets, code style and docblocks, and the checks to run before you open a pull request.</p></div><h2 id="ways-to-contribute" tabindex="-1">Ways to Contribute <a class="header-anchor" href="#ways-to-contribute" aria-label="Permalink to &quot;Ways to Contribute&quot;">​</a></h2><ul><li><strong>Report a bug.</strong> A pull request with a test that fails because of the bug is a welcome form of report.</li><li><strong>Propose a feature.</strong> Agree the approach in a feature request before you build it.</li><li><strong>Fix an issue or build an agreed feature.</strong> Comment on the issue and wait to be assigned before you write code.</li><li><strong>Improve a translation.</strong> Locale files are in each package&#39;s <code>src/Resources/lang/&lt;locale&gt;/</code> directory, and every key must exist in all 22 locales.</li><li><strong>Improve the documentation.</strong> Each page of this site links to its source in <a href="https://github.com/bagisto/bagisto-docs" target="_blank" rel="noreferrer">bagisto/bagisto-docs</a>; the merchant user guide is in <a href="https://github.com/bagisto/user-guide" target="_blank" rel="noreferrer">bagisto/user-guide</a>.</li></ul><h2 id="reporting-a-bug" tabindex="-1">Reporting a Bug <a class="header-anchor" href="#reporting-a-bug" aria-label="Permalink to &quot;Reporting a Bug&quot;">​</a></h2><ol><li>Search the <a href="https://github.com/bagisto/bagisto/issues" target="_blank" rel="noreferrer">issues</a> for an existing report.</li><li>Check that the problem is in Bagisto and not in your own setup. Ask for help with your own installation on the <a href="https://forums.bagisto.com/" target="_blank" rel="noreferrer">community forum</a>.</li><li><a href="https://github.com/bagisto/bagisto/issues/new/choose" target="_blank" rel="noreferrer">Open an issue</a> with the bug report form. It asks for the affected version, your environment, the steps to reproduce, and the expected and actual results.</li></ol><p>Feature requests use the same page: choose the feature request form.</p><h2 id="security-vulnerabilities" tabindex="-1">Security Vulnerabilities <a class="header-anchor" href="#security-vulnerabilities" aria-label="Permalink to &quot;Security Vulnerabilities&quot;">​</a></h2><p>Don&#39;t report a security vulnerability in the public issue tracker, and don&#39;t disclose it publicly. Email the details to <a href="mailto:support@bagisto.com" target="_blank" rel="noreferrer">support@bagisto.com</a>, or open a ticket at <a href="https://bagisto.uvdesk.com/en/" target="_blank" rel="noreferrer">Bagisto Support</a>, as the repository&#39;s <a href="https://github.com/bagisto/bagisto/blob/master/SECURITY.md" target="_blank" rel="noreferrer"><code>SECURITY.md</code></a> describes.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../advanced/coding-standards.html">Coding Standards</a>: Pint, the conventions a review checks, and the translations check.</li><li><a href="./../advanced/testing.html">Testing Overview</a>: how Bagisto&#39;s Pest tests and Playwright end-to-end tests are organized and run.</li><li><a href="./../package-development/getting-started.html">Package Development</a>: how a Bagisto package is built and registered; every core module is one.</li><li><a href="./../ai/agent-skills.html">Agent Skills</a>: <code>bagisto-git-workflow</code> and <code>bagisto-code-review</code> give a coding agent Bagisto&#39;s branch, commit and review conventions.</li></ul>',12)]))}const b=t(i,[["render",s]]);export{h as __pageData,b as default};
